import { loginAs, sessionAs, test } from '../bazis';

import { PRODUCT } from './product';

test('manager-opens-a-suggested-task', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  const asVisitor = await test.step('as: visitor', () => sessionAs(app, 'visitor'));
  await test.step('open: suggest-task', async () => {
    await asVisitor.open('suggest-task');
  });
  await test.step('fill: {title: Suggested for the manager}', async () => {
    await asVisitor.fill({ title: 'Suggested for the manager' });
  });
  await test.step('submit', async () => {
    await asVisitor.submit({ saved: true });
  });
  const $suggested = await test.step('remember: {suggested: title}', () => asVisitor.answer('title'));
  await test.step('as: manager', () => app.page.bringToFront());
  await test.step('open_item: {where: {title: $suggested}}', async () => {
    await app.openItem({ where: { title: $suggested } });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
});
